/* Signature Mongolian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Batbold": "From bat (firm) + bold (steel): 'firm steel'.", "Oyuunnaran": "From oyuun (wisdom) + naran (sun): 'sun of wisdom'.", "Altanbat": "From altan (gold) + bat (firm): 'firm gold'.", "Munkhbat": "From munkh (eternal) + bat (firm): 'eternally firm'.", "Naransaran": "From naran (sun) + saran (moon): 'sun and moon'.", "Tumurbat": "From tumur (iron) + bat (firm): 'firm iron'.", "Batboldyn": "Signature patronymic-style surname: 'of Batbold'.", "Oyuunbatyn": "Signature patronymic-style surname.", "Altanovog": "Signature clan-style surname: 'clan of gold'.", "Munkhkhiyad": "Signature clan-style surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Batbold';
console.log(lookup(q));

